package com.adc.infrastructure;
import static org.junit.jupiter.api.Assertions.*;
import com.adc.application.*;
import com.adc.domain.shared.DomainFailure;
import java.util.*;
import org.junit.jupiter.api.*;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ClinicalTreatmentsIT {
    final AppointmentTransitionsIT fixture=new AppointmentTransitionsIT();ClinicalTreatmentService clinical;String doctorToken=Crypto.token();
    @BeforeAll void migrate()throws Exception{fixture.migrate();}
    @AfterAll void dispose(){fixture.dispose();}
    @BeforeEach void setup()throws Exception{
        fixture.setup();var base=fixture.base();base.context.register(ClinicalTreatmentStore.class,ClinicalTreatmentService.class);clinical=base.context.getBean(ClinicalTreatmentService.class);fixture.attendance.attend(fixture.command("attendAppointment","attend"),fixture.id,fixture.fixture.proof);
        base.db.update("INSERT INTO adc_business.Dentist (dentist_id,employee_number,full_name,date_of_birth,home_address,phone,email,hire_date,is_active,created_at,termination_date) VALUES (22,'D-22','Fictional actual dentist','1980-01-01',NULL,'000',NULL,'2020-01-01',true,?,NULL)",StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_business.DentistClinicAssignment VALUES (42,22,1,'2020-01-01',NULL,NULL,true)");
        base.db.update("INSERT INTO adc_identity.Subject VALUES ('clinical-dentist','STAFF',true,?,NULL)",StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_identity.StaffAccount VALUES ('clinical-dentist','clinical-dentist','Verified fixture',22,?,false,?,'fixture')",base.context.getBean(com.adc.identity.PasswordHasher.class).encode("isolated-fixture-password"),StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_identity.Session VALUES ('clinical-session','clinical-dentist',?,'WEB',?, ?,?,?,NULL,NULL)",Crypto.sha256(doctorToken),new byte[32],StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now.plusSeconds(28800)));
        base.db.update("INSERT INTO adc_identity.AccessGrant VALUES ('clinical-grant','clinical-dentist','DENTIST','hq',?,NULL,NULL,NULL,'fixture',?)",StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('clinical-grant',1)");for(String capability:List.of("recordAppliedTreatment","getClinicalContext","getAppliedTreatment","completeAppointment","updateClinicalNotes"))base.db.update("INSERT INTO adc_identity.GrantCapability VALUES ('clinical-grant',?)",capability);base.db.update("INSERT INTO adc_identity.GrantCapability VALUES ('hq','correctTreatmentPrice')");base.db.update("UPDATE adc_business.Treatment SET default_unit_price=10.01 WHERE treatment_id=71");base.db.update("INSERT INTO adc_business.Treatment VALUES (72,'FREE-CONSULT','Actual free consultation',NULL,0.00,true)");
    }
    @AfterEach void close(){fixture.close();}
    AtomicCommandExecutor.Command command(String operation,String key){return new AtomicCommandExecutor.Command(doctorToken,"WEB",operation,key,Crypto.sha256(key),UUID.randomUUID().toString());}
    Map<String,Object> record(String key,long treatment,String units)throws Exception{return clinical.record(command("recordAppliedTreatment",key),fixture.id,new ClinicalTreatmentService.Record(treatment,units,fixture.base().now));}
    @Test void substitutePerformerExactRoundingHistoricalPriceAndCompletionHaveRealFacts()throws Exception{
        var row=record("record",71,"1.50");assertEquals("22",row.get("dentist_id"));assertEquals("15.02",row.get("subtotal"));assertEquals(row,record("record",71,"1.50"));fixture.base().db.update("UPDATE adc_business.Treatment SET default_unit_price=99.00 WHERE treatment_id=71");assertEquals("10.01",clinical.applied(doctorToken,"WEB",Long.parseLong((String)row.get("applied_treatment_id")),UUID.randomUUID().toString()).get("unit_price"));var completed=clinical.complete(command("completeAppointment","complete"),fixture.id);assertEquals("COMPLETED",completed.get("status"));assertNotNull(completed.get("completed_at"));assertThrows(DomainFailure.class,()->record("after-complete",71,"1.00"));assertEquals(0,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_business.Invoice",Integer.class));
    }
    @Test void zeroUnitsInactiveCatalogQualificationAndEmptyCompletionAreRejectedButFreeActualCareIsAllowed()throws Exception{
        assertThrows(IllegalArgumentException.class,()->record("zero",71,"0"));assertThrows(DomainFailure.class,()->clinical.complete(command("completeAppointment","empty"),fixture.id));fixture.base().db.update("UPDATE adc_business.Treatment SET is_active=false WHERE treatment_id=71");assertThrows(DomainFailure.class,()->record("inactive",71,"1.00"));record("free-actual",72,"1.00");assertEquals("COMPLETED",clinical.complete(command("completeAppointment","free-complete"),fixture.id).get("status"));
    }
    @Test void clinicalRiskContextIsMinimalAndReceptionCannotRecordAsDentist()throws Exception{
        var context=clinical.context(doctorToken,"WEB",fixture.id,UUID.randomUUID().toString());assertTrue(context.containsKey("patient_allergy_review_status"));String json=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(context);assertFalse(json.contains("billing_address"));assertFalse(json.contains("date_of_birth"));assertThrows(DomainFailure.class,()->clinical.record(fixture.command("recordAppliedTreatment","reception-spoof"),fixture.id,new ClinicalTreatmentService.Record(71,"1.00",fixture.base().now)));
    }
    @Test void separatePriceAuthorityRequiresAuditedSnapshotAndIfMatchAndKeepsOldNewValues()throws Exception{
        var row=record("record",71,"1.50");long id=Long.parseLong((String)row.get("applied_treatment_id"));String etag=(String)row.get("etag");assertThrows(DomainFailure.class,()->clinical.correct(command("correctTreatmentPrice","doctor-price"),id,"20.00","自行改价",etag,etag));assertThrows(DomainFailure.class,()->clinical.correct(new AtomicCommandExecutor.Command(fixture.base().token,"WEB","correctTreatmentPrice","unverified-price",Crypto.sha256("unverified-price"),UUID.randomUUID().toString()),id,"20.00","没有本人的服务器核验读取",etag,etag));var verified=clinical.applied(fixture.base().token,"WEB",id,UUID.randomUUID().toString());String reference=(String)verified.get("etag");var corrected=clinical.correct(new AtomicCommandExecutor.Command(fixture.base().token,"WEB","correctTreatmentPrice","correct",Crypto.sha256("correct"),UUID.randomUUID().toString()),id,"20.00","授权核验后纠错",reference,reference);assertEquals("30.00",corrected.get("subtotal"));assertEquals("20.00",corrected.get("unit_price"));assertTrue(fixture.base().db.queryForObject("SELECT change_summary FROM adc_audit.AuditEvent WHERE action='correctTreatmentPrice' AND result='SUCCESS'",String.class).contains("10.01"));
    }
    @Test void notesVersionChangesAndStaleWritesCannotSilentlyOverwriteClinicalText()throws Exception{
        var context=clinical.context(doctorToken,"WEB",fixture.id,UUID.randomUUID().toString());var version=new LinkedHashMap<String,Object>();version.put("appointment",context.get("appointment"));version.put("problems_or_special_needs",context.get("problems_or_special_needs"));String etag=CanonicalJson.etag(tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(version));var saved=clinical.notes(command("updateClinicalNotes","note"),fixture.id,"已核实特殊需求",etag);assertNotEquals(etag,saved.etag());assertThrows(DomainFailure.class,()->clinical.notes(command("updateClinicalNotes","stale-note"),fixture.id,"过时覆盖",etag));assertEquals("已核实特殊需求",clinical.context(doctorToken,"WEB",fixture.id,UUID.randomUUID().toString()).get("problems_or_special_needs"));
    }
    @Test void inactiveOrUnverifiedRequiredQualificationBlocksActualCareAndAuditFailureRollsItBack()throws Exception{
        var db=fixture.base().db;db.update("INSERT INTO adc_business.Qualification VALUES (81,'Required clinical qualification',NULL,true)");db.update("INSERT INTO adc_business.TreatmentQualification VALUES (71,81,true)");assertThrows(DomainFailure.class,()->record("missing-qualification",71,"1.00"));db.update("INSERT INTO adc_business.DentistQualification VALUES (22,81,'verified-fixture','2020-01-01',NULL,'VERIFIED')");
        try(var connection=fixture.base().connection("inspector");var sql=connection.createStatement()){sql.execute("REVOKE INSERT ON adc_audit.* FROM 'adc_runtime_role'");try{assertThrows(org.springframework.dao.DataAccessException.class,()->record("rollback-care",71,"1.50"));}finally{sql.execute("GRANT INSERT ON adc_audit.* TO 'adc_runtime_role'");}}assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM adc_business.AppliedTreatment",Integer.class));assertEquals("IN_PROGRESS",db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));
    }
    @Test void invoicedHistoricalTreatmentAndInvoiceSnapshotRemainReadOnly()throws Exception{
        var row=record("record",71,"1.50");long id=Long.parseLong((String)row.get("applied_treatment_id"));clinical.complete(command("completeAppointment","complete"),fixture.id);var db=fixture.base().db;db.update("INSERT INTO adc_business.Invoice VALUES (91,'OWNED-HISTORY-INVOICE',?,?,15.02,'ISSUED',?)",fixture.id,StaffAccountsIT.utc(fixture.base().now),StaffAccountsIT.utc(fixture.base().now));db.update("INSERT INTO adc_business.InvoiceItem VALUES (92,91,?,1,'Owned invoice snapshot',1.50,10.01,15.02)",id);db.update("UPDATE adc_business.Appointment SET status='INVOICED' WHERE appointment_id=?",fixture.id);var verified=clinical.applied(fixture.base().token,"WEB",id,UUID.randomUUID().toString());String etag=(String)verified.get("etag");assertThrows(DomainFailure.class,()->clinical.correct(new AtomicCommandExecutor.Command(fixture.base().token,"WEB","correctTreatmentPrice","after-invoice",Crypto.sha256("after-invoice"),UUID.randomUUID().toString()),id,"20.00","开票后不可改价",etag,etag));assertThrows(DomainFailure.class,()->record("after-invoice-care",72,"1.00"));assertEquals("10.01",db.queryForObject("SELECT unit_price FROM adc_business.InvoiceItem WHERE invoice_item_id=92",java.math.BigDecimal.class).toPlainString());
    }
    @Test void completionAndAnotherDentistsNewRecordSerializeBeforeTheReadOnlyBoundary()throws Exception{
        record("first",71,"1.00");var base=fixture.base();String other=Crypto.token();base.db.update("INSERT INTO adc_identity.Subject VALUES ('clinical-second','STAFF',true,?,NULL)",StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_identity.StaffAccount SELECT 'clinical-second','clinical-second','Verified second fixture',21,password_hash,false,credential_changed_at,'fixture' FROM adc_identity.StaffAccount WHERE subject_id='clinical-dentist'");base.db.update("INSERT INTO adc_identity.Session VALUES ('clinical-second-session','clinical-second',?,'WEB',?, ?,?,?,NULL,NULL)",Crypto.sha256(other),new byte[32],StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now.plusSeconds(28800)));base.db.update("INSERT INTO adc_identity.AccessGrant VALUES ('clinical-second-grant','clinical-second','DENTIST','hq',?,NULL,NULL,NULL,'fixture',?)",StaffAccountsIT.utc(base.now),StaffAccountsIT.utc(base.now));base.db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('clinical-second-grant',1)");base.db.update("INSERT INTO adc_identity.GrantCapability VALUES ('clinical-second-grant','recordAppliedTreatment')");
        try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var complete=pool.submit(()->{start.await();clinical.complete(command("completeAppointment","race-complete"),fixture.id);return 200;});var record=pool.submit(()->{start.await();try{clinical.record(new AtomicCommandExecutor.Command(other,"WEB","recordAppliedTreatment","race-add",Crypto.sha256("race-add"),UUID.randomUUID().toString()),fixture.id,new ClinicalTreatmentService.Record(71,"1.00",base.now));return 200;}catch(DomainFailure failure){return failure.status();}});start.countDown();assertEquals(200,complete.get(20,java.util.concurrent.TimeUnit.SECONDS));int result=record.get(20,java.util.concurrent.TimeUnit.SECONDS);assertTrue(Set.of(200,409).contains(result));assertEquals(result==200?2:1,base.db.queryForObject("SELECT COUNT(*) FROM adc_business.AppliedTreatment",Integer.class));}
        assertEquals("COMPLETED",base.db.queryForObject("SELECT status FROM adc_business.Appointment WHERE appointment_id=?",String.class,fixture.id));assertEquals(1,base.db.queryForObject("SELECT COUNT(*) FROM adc_business.AppointmentEvent WHERE event_type='COMPLETE'",Integer.class));
    }
    @Test void unauthorizedClinicalAndActualTreatmentReadsProduceFailureAuditWithoutDisclosure()throws Exception{
        var applied=record("actual",71,"1.00");String first=UUID.randomUUID().toString(),second=UUID.randomUUID().toString();assertThrows(DomainFailure.class,()->clinical.context(fixture.base().other,"WEB",fixture.id,first));assertThrows(DomainFailure.class,()->clinical.applied(fixture.base().other,"WEB",Long.parseLong((String)applied.get("applied_treatment_id")),second));assertEquals(2,fixture.base().db.queryForObject("SELECT COUNT(*) FROM adc_audit.AuditEvent WHERE request_id IN (?,?) AND result='FAILURE'",Integer.class,first,second));
    }
}
